const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '!dataset/**' /app /tmp/codex-home 2>/dev/null",max_output_tokens:4000}),
  tools.exec_command({cmd:"ls -l /app/dataset && head -n 12 /app/dataset/farms.csv && head -n 15 /app/dataset/farm_registry.csv && head -n 12 /app/dataset/production_FARM_A.csv",max_output_tokens:5000}),
  tools.exec_command({cmd:"cat /app/dataset/sensors_calibration.json /app/dataset/maintenance_notes.txt",max_output_tokens:18000})
]);
for (let i=0;i<results.length;i++) text({i,...results[i]});

